<?php
namespace SerbenConnect\Services; use SerbenConnect\API\Client;
if(!defined('ABSPATH')){exit;} final class ProdutosService{private $c;function __construct(?Client $c=null){$this->c=$c?:new Client();}function listar(int $page=1,int $limit=100):array{return $this->c->integrationGet('clube_beneficio','Produtos/listarProdutos',['page'=>max(1,$page),'limit'=>min(100,max(1,$limit))]);}function getPorId(int $id):array{return $this->c->integrationGet('clube_beneficio','Produtos/getProdutoPorId',['id_produto'=>$id]);}function cadastrar(array $p):array{return $this->c->integrationPost('clube_beneficio','Produtos/cadastrarProduto',$p);}function editar(int $id,array $p):array{$p['id_produto']=$id;return $this->c->integrationPost('clube_beneficio','Produtos/editarProduto',$p);}}
